from collections import deque
import math


class ExactStrategySystem(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_closes = deque(maxlen=200)
        self.spy_sma50_previous = None
        self.spy_sma200_previous = None

        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)
        self.aapl_previous_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0
        self.strategy_a_pending = False
        self.strategy_b_pending = False

        self.SetWarmUp(250, Resolution.Daily)

    def OnData(self, data):
        self._update_market_state(data)

        if self.IsWarmingUp:
            return

        if any(symbol not in data.Bars for symbol in self.symbols):
            return

        spy_bar = data.Bars[self.spy]
        aapl_bar = data.Bars[self.aapl]

        spy_close = float(spy_bar.Close)
        aapl_close = float(aapl_bar.Close)

        spy_sma50 = self._sma(self.spy_closes, 50)
        spy_sma200 = self._sma(self.spy_closes, 200)

        if spy_sma50 is None or spy_sma200 is None:
            return

        if self.strategy_a_lot > 0 and not self.strategy_a_pending:
            sell_a = (
                self.spy_sma50_previous is not None
                and self._crosses_below(
                    self.spy_sma50_previous,
                    spy_close,
                    spy_sma50
                )
            )

            if sell_a:
                self.strategy_a_pending = True
                self.MarketOrder(
                    self.spy,
                    -self.strategy_a_lot,
                    tag="STRATEGY_A_SELL"
                )

        if self.strategy_b_lot > 0 and not self.strategy_b_pending:
            if self.aapl_rsi.IsReady and self.aapl_rsi.Current.Value > 60:
                self.strategy_b_pending = True
                self.MarketOrder(
                    self.aapl,
                    -self.strategy_b_lot,
                    tag="STRATEGY_B_SELL"
                )

        if self.strategy_a_lot == 0 and not self.strategy_a_pending:
            buy_a = (
                self.spy_sma200_previous is not None
                and self._crosses_above(
                    self.spy_sma200_previous,
                    spy_close,
                    spy_sma200
                )
            )

            if buy_a:
                quantity = int(
                    math.floor(
                        0.40 * self.Portfolio.TotalPortfolioValue / spy_close
                    )
                )

                if quantity > 0:
                    self.strategy_a_pending = True
                    self.MarketOrder(
                        self.spy,
                        quantity,
                        tag="STRATEGY_A_BUY"
                    )

        if self.strategy_b_lot == 0 and not self.strategy_b_pending:
            if self.aapl_red_streak >= 3:
                if self.Portfolio.Cash >= 20000:
                    quantity = int(math.floor(20000 / aapl_close))

                    if quantity > 0:
                        self.strategy_b_pending = True
                        self.MarketOrder(
                            self.aapl,
                            quantity,
                            tag="STRATEGY_B_BUY"
                        )

        self.spy_sma50_previous = spy_sma50
        self.spy_sma200_previous = spy_sma200

    def _update_market_state(self, data):
        if self.spy in data.Bars:
            spy_close = float(data.Bars[self.spy].Close)
            self.spy_closes.append(spy_close)

        if self.aapl in data.Bars:
            aapl_close = float(data.Bars[self.aapl].Close)

            if self.aapl_previous_close is not None:
                if aapl_close < self.aapl_previous_close:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

            self.aapl_rsi.Update(
                IndicatorDataPoint(self.Time, aapl_close)
            )
            self.aapl_previous_close = aapl_close

    @staticmethod
    def _sma(values, period):
        if len(values) < period:
            return None
        return sum(list(values)[-period:]) / period

    @staticmethod
    def _crosses_above(previous_x, today_x, today_y):
        return previous_x <= today_y and today_x > today_y

    @staticmethod
    def _crosses_below(previous_x, today_x, today_y):
        return previous_x >= today_y and today_x < today_y

    def OnOrderEvent(self, orderEvent):
        if orderEvent.Status not in [
            OrderStatus.Filled,
            OrderStatus.PartiallyFilled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Marginบrejected
        ]:
            return

        tag = orderEvent.Tag
        quantity = int(orderEvent.FillQuantity)

        if tag == "STRATEGY_A_BUY":
            self.strategy_a_lot += max(quantity, 0)
            if orderEvent.Status != OrderStatus.PartiallyFilled:
                self.strategy_a_pending = False

        elif tag == "STRATEGY_A_SELL":
            self.strategy_a_lot = max(0, self.strategy_a_lot + min(quantity, 0))
            if orderEvent.Status != OrderStatus.PartiallyFilled:
                self.strategy_a_pending = False

        elif tag == "STRATEGY_B_BUY":
            self.strategy_b_lot += max(quantity, 0)
            if orderEvent.Status != OrderStatus.PartiallyFilled:
                self.strategy_b_pending = False

        elif tag == "STRATEGY_B_SELL":
            self.strategy_b_lot = max(0, self.strategy_b_lot + min(quantity, 0))
            if orderEvent.Status != OrderStatus.PartiallyFilled:
                self.strategy_b_pending = False
