        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_sma200 = self.SMA(self.spy, 200, Resolution.Daily)
        self.spy_sma50 = self.SMA(self.spy, 50, Resolution.Daily)
        self.aapl_rsi14 = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.SetWarmUp(200, Resolution.Daily)

        self.previous_closes = {}
        self.previous_sma200 = None
        self.previous_sma50 = None
        self.aapl_red_streak = 0

        self.spy_lot = 0
        self.aapl_lot = 0
        self.spy_pending = False
        self.aapl_pending = False

    def OnData(self, data):
        available = {
            symbol: data.Bars[symbol].Close
            for symbol in self.symbols
            if symbol in data.Bars
        }

        if self.aapl in available:
            previous = self.previous_closes.get(self.aapl)
            if previous is not None:
                if available[self.aapl] < previous:
                    self.aapl_red_streak += 1
                else:
                    self.aapl_red_streak = 0

        for symbol, close in available.items():
            self.previous_closes[symbol] = close

        if self.spy_sma200.IsReady:
            current_sma200 = self.spy_sma200.Current.Value
        else:
            current_sma200 = None

        if self.spy_sma50.IsReady:
            current_sma50 = self.spy_sma50.Current.Value
        else:
            current_sma50 = None

        if self.IsWarmingUp:
            if current_sma200 is not None:
                self.previous_sma200 = current_sma200
            if current_sma50 is not None:
                self.previous_sma50 = current_sma50
            return

        if len(available) != len(self.symbols):
            if current_sma200 is not None:
                self.previous_sma200 = current_sma200
            if current_sma50 is not None:
                self.previous_sma50 = current_sma50
            return

        spy_close = available[self.spy]
        aapl_close = available[self.aapl]

        spy_sell = (
            self.spy_lot > 0
            and not self.spy_pending
            and self.previous_closes.get(self.spy) is not None
            and self.previous_sma50 is not None
            and current_sma50 is not None
            and self.previous_closes[self.spy] >= self.previous_sma50
            and spy_close < current_sma50
        )

        aapl_sell = (
            self.aapl_lot > 0
            and not self.aapl_pending
            and self.aapl_rsi14.IsReady
            and self.aapl_rsi14.Current.Value > 60
        )

        if spy_sell:
            self.spy_pending = True
            self.MarketOrder(self.spy, -self.spy_lot, "Strategy A sell")

        if aapl_sell:
            self.aapl_pending = True
            self.MarketOrder(self.aapl, -self.aapl_lot, "Strategy B sell")

        spy_buy = (
            self.spy_lot == 0
            and not self.spy_pending
            and self.previous_closes.get(self.spy) is not None
            and self.previous_sma200 is not None
            and current_sma200 is not None
            and self.previous_closes[self.spy] <= self.previous_sma200
            and spy_close > current_sma200
        )

        aapl_buy = (
            self.aapl_lot == 0
            and not self.aapl_pending
            and self.aapl_red_streak >= 3
            and self.Portfolio.Cash >= 20000
        )

        if spy_buy:
            quantity = int(
                (0.40 * self.Portfolio.TotalPortfolioValue) / spy_close
            )
            if quantity > 0:
                self.spy_pending = True
                self.MarketOrder(self.spy, quantity, "Strategy A buy")

        if aapl_buy:
            quantity = int(20000 / aapl_close)
            if quantity > 0:
                self.aapl_pending = True
                self.MarketOrder(self.aapl, quantity, "Strategy B buy")

        if current_sma200 is not None:
            self.previous_sma200 = current_sma200
        if current_sma50 is not None:
            self.previous_sma50 = current_sma50

    def OnOrderEvent(self, order_event):
        if order_event.Status != OrderStatus.Filled:
            if order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None
            ]:
                if "Strategy A" in order_event.Tag:
                    self.spy_pending = False
                elif "Strategy B" in order_event.Tag:
                    self.aapl_pending = False
            return

        if "Strategy A" in order_event.Tag:
            self.spy_lot += order_event.FillQuantity
            self.spy_pending = False
            if self.spy_lot < 0:
                self.spy_lot = 0

        elif "Strategy B" in order_event.Tag:
            self.aapl_lot += order_event.FillQuantity
            self.aapl_pending = False
            if self.aapl_lot < 0:
                self.aapl_lot = 0
